public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> res = new ArrayList<>();
    if (nums == null) {
        return res;
    }
    int n = nums.length;
    if (n == 0) {
        res.add(new ArrayList<>());
        return res;
    }
    boolean[] visited = new boolean[n];
    List<Integer> path = new ArrayList<>(n);
    backtrack(nums, visited, path, res);
    return res;
}

private void backtrack(int[] nums, boolean[] visited, List<Integer> path, List<List<Integer>> res) {
    if (path.size() == nums.length) {
        res.add(new ArrayList<>(path));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (!visited[i]) {
            visited[i] = true;
            path.add(nums[i]);
            backtrack(nums, visited, path, res);
            path.remove(path.size() - 1);
            visited[i] = false;
        }
    }
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums == null) {
        return result;
    }
    // Start with a single empty permutation
    result.add(new ArrayList<>());
    for (int num : nums) {
        List<List<Integer>> newResult = new ArrayList<>();
        for (List<Integer> perm : result) {
            // Insert the current number at every possible position
            for (int i = 0; i <= perm.size(); i++) {
                List<Integer> newPerm = new ArrayList<>(perm);
                newPerm.add(i, num);
                newResult.add(newPerm);
            }
        }
        result = newResult;
    }
    // Special case for empty input to match typical LeetCode expectation
    if (nums.length == 0) {
        result.clear();
        result.add(new ArrayList<>());
    }
    return result;
