public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Find the shortest string to minimize substring enumeration
    int minIndex = 0;
    for (int i = 1; i < strings.size(); i++) {
        if (strings.get(i).length() < strings.get(minIndex).length()) {
            minIndex = i;
        }
    }
    String base = strings.get(minIndex);
    if (base.isEmpty()) {
        return 0; // No non-empty substring can be common to all
    }
    int best = 0;
    int baseLen = base.length();
    // Iterate lengths from longest to shortest
    for (int len = baseLen; len > 0; len--) {
        // If we already found a valid substring of this length, return it
        if (len <= best) {
            break;
        }
