            best = len;
            // Since we are scanning lengths descending, this is the maximum
            return best;
        }
    }
    return best;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    int maxLen = 0;
    for (String s : strings) {
        if (s != null && s.length() > maxLen) {
            maxLen = s.length();
        }
    }
    // Try lengths from maxLen down to 1
    for (int len = maxLen; len >= 1; len--) {
        java.util.HashSet<String> candidates = new java.util.HashSet<>();
        // Gather all substrings of this length from all strings
        for (String s : strings) {
            if (s == null || s.length() < len) {
                continue;
            }
            for (int i = 0; i <= s.length() - len; i++) {
                candidates.add(s.substring(i, i + len));
            }
        }
        // Check each candidate
        for (String cand : candidates) {
            String rev = new StringBuilder(cand).reverse().toString();
            boolean ok = true;
            for (String s : strings) {
                if (s == null) {
                    ok = false;
                    break;
                }
                if (!(s.contains(cand) || s.contains(rev))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
