            return sb.toString();
        };
        java.util.Map<java.lang.String, java.util.Set<java.lang.String>> graph = new java.util.HashMap<>();
        // Build graph from paths
        for (int[] path : paths) {
            if (path == null || path.length != 2 * n) {
                // Invalid path format
                continue;
            }
            int[] coordA = new int[n];
            int[] coordB = new int[n];
            System.arraycopy(path, 0, coordA, 0, n);
            System.arraycopy(path, n, coordB, 0, n);
            java.lang.String keyA = coordToKey.apply(coordA);
            java.lang.String keyB = coordToKey.apply(coordB);
            graph.computeIfAbsent(keyA, k -> new java.util.HashSet<>()).add(keyB);
            graph.computeIfAbsent(keyB, k -> new java.util.HashSet<>()).add(keyA);
        }
        java.lang.String startKey = coordToKey.apply(start);
        java.lang.String endKey = coordToKey.apply(end);
        if (!graph.containsKey(startKey) || !graph.containsKey(endKey)) {
            return "cannot be travelled";
        }
        // BFS to find path
        java.util.Queue<java.lang.String> queue = new java.util.ArrayDeque<>();
        java.util.Set<java.lang.String> visited = new java.util.HashSet<>();
        queue.add(startKey);
        visited.add(startKey);
