            java.lang.String current = queue.poll();
            if (current.equals(endKey)) {
                return "can be travelled";
            }
            java.util.Set<java.lang.String> neighbors = graph.getOrDefault(current, java.util.Collections.emptySet());
            for (java.lang.String nei : neighbors) {
                if (!visited.contains(nei)) {
                    visited.add(nei);
                    queue.add(nei);
                }
            }
        }
        return "cannot be travelled";
    } catch (Exception e) {
