public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0) return "cannot be travelled";
    if (start == null || end == null || start.length != n || end.length != n) {
        return "cannot be travelled";
    }
    // Helper to convert coordinate array to a unique key
    java.util.function.Function<int[], String> keyOf = coord -> {
        if (coord == null || coord.length != n) return null;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            sb.append(coord[i]);
            if (i < n - 1) sb.append(',');
        }
        return sb.toString();
    };
    String startKey = keyOf.apply(start);
    String endKey = keyOf.apply(end);
    if (startKey == null || endKey == null) return "cannot be travelled";

    java.util.Map<String, java.util.List<String>> adjacency = new java.util.HashMap<>();
    if (paths != null) {
        for (int[] p : paths) {
            if (p == null) continue;
            int expectedLen = 2 * n;
            if (p.length != expectedLen) continue; // invalid path definition
            int[] coord1 = new int[n];
            int[] coord2 = new int[n];
            System.arraycopy(p, 0, coord1, 0, n);
            System.arraycopy(p, n, coord2, 0, n);
            String key1 = keyOf.apply(coord1);
            String key2 = keyOf.apply(coord2);
            if (key1 == null || key2 == null) continue;
            adjacency.computeIfAbsent(key1, k -> new java.util.ArrayList<>()).add(key2);
            adjacency.computeIfAbsent(key2, k -> new java.util.ArrayList<>()).add(key1);
        }
    }

    java.util.Queue<String> q = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    q.offer(startKey);
    visited.add(startKey);
    while (!q.isEmpty()) {
        String current = q.poll();
        if (current.equals(endKey)) {
            return "can be travelled";
        }
        java.util.List<String> neighbors = adjacency.get(current);
        if (neighbors != null) {
            for (String nb : neighbors) {
                if (!visited.contains(nb)) {
                    visited.add(nb);
                    q.offer(nb);
                }
            }
        }
    }
    return "cannot be travelled";
}

public static String appx(String word1, String word2) {
    if (word1 == null) word1 = "";
    if (word2 == null) word2 = "";
    int len1 = word1.length();
    int len2 = word2.length();
    int sumLen = len1 + len2;
    // If both strings are empty, define similarity as 0
    if (sumLen == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }
    // Frequency map for characters of the second word
    java.util.HashMap<Character, Integer> freq2 = new java.util.HashMap<>();
    for (int i = 0; i < len2; i++) {
        char c = word2.charAt(i);
        freq2.put(c, freq2.getOrDefault(c, 0) + 1);
    }
    // Compute sum of freq1 * freq2
    long commonProductSum = 0;
    for (int i = 0; i < len1; i++) {
        char c = word1.charAt(i);
        int f2 = freq2.getOrDefault(c, 0);
        if (f2 > 0) {
            commonProductSum += f2;
        }
    }
    // Build freq map for first word for the other direction
    java.util.HashMap<Character, Integer> freq1 = new java.util.HashMap<>();
    for (int i = 0; i < len1; i++) {
        char c = word1.charAt(i);
        freq1.put(c, freq1.getOrDefault(c, 0) + 1);
    }
    for (int i = 0; i < len2; i++) {
        char c = word2.charAt(i);
        int f1 = freq1.getOrDefault(c, 0);
        if (f1 > 0) {
            commonProductSum += f1;
        }
    }
    // The numerator is twice the product sum
    long numerator = 2L * commonProductSum;
    long denominator = sumLen;
    String result;
    if (numerator == 0) {
        result = "0";
    } else {
        long g = java.lang.Math.abs(gcd(numerator, denominator));
        long numReduced = numerator / g;
        long denReduced = denominator / g;
        if (denReduced == 1) {
            result = String.valueOf(numReduced);
        } else {
            result = numReduced + "/" + denReduced;
        }
    }
    return "appx(" + word1 + ", " + word2 + ") = " + result;
}

private static long gcd(long a, long b) {
    a = Math.abs(a);
    b = Math.abs(b);
    while (b != 0) {
        long t = b;
        b = a % b;
        a = t;
    }
    return a;
}

public static String convertDatesToWeekdays(String date) {
    if (date == null) {
        throw new IllegalArgumentException("Input date string cannot be null.");
    }
    String[] parts = date.trim().split("\\s+");
    if (parts.length != 3) {
        throw new IllegalArgumentException("Input must be in the format \"MM dd yyyy\".");
    }
    int month, day, year;
    try {
        month = Integer.parseInt(parts[0]);
        day = Integer.parseInt(parts[1]);
        year = Integer.parseInt(parts[2]);
    } catch (NumberFormatException e) {
        throw new IllegalArgumentException("Month, day, and year must be numeric.", e);
    }
    java.time.LocalDate localDate;
    try {
        localDate = java.time.LocalDate.of(year, month, day);
    } catch (java.time.DateTimeException e) {
        throw new IllegalArgumentException("Invalid date provided.", e);
    }
    String monthName = localDate.getMonth()
            .getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
    String weekday = localDate.getDayOfWeek()
            .getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
