public static String convertDatesToWeekdays(String date) {
    if (date == null) {
        return null;
    }
    String[] parts = date.trim().split("\\s+");
    if (parts.length != 3) {
        return null;
    }
    try {
        int month = Integer.parseInt(parts[0]);
        int day   = Integer.parseInt(parts[1]);
        int year  = Integer.parseInt(parts[2]);

        if (month < 1 || month > 12 || day < 1 || day > 31) {
            return null;
        }

        String[] monthNames = {
            "January", "February", "March", "April", "May", "June",
            "July", "August", "September", "October", "November", "December"
        };
        String monthName = monthNames[month - 1];

        // Zeller's Congruence for Gregorian calendar
        int m = month;
        int Y = year;
        if (m <= 2) {
            m += 12;
            Y -= 1;
        }
        int K = Y % 100;
        int J = Y / 100;
        int h = (day + (13 * (m + 1)) / 5 + K + K / 4 + J / 4 + 5 * J) % 7;

        String[] weekNames = {
            "Saturday", "Sunday", "Monday", "Tuesday",
            "Wednesday", "Thursday", "Friday"
        };
        String weekday = weekNames[h];

        return String.format("%s %d, %d is a %s", monthName, day, year, weekday);
    } catch (Exception e) {
        // Covers NumberFormatException and arithmetic exceptions
        return null;
    }
}

