public int[] twoSum(int[] nums, int target) {
    if (nums == null || nums.length < 2) {
        throw new IllegalArgumentException("Input array must contain at least two elements");
    }
    java.util.Map<Integer, Integer> map = new java.util.HashMap<>();
    try {
        for (int i = 0; i < nums.length; i++) {
            int complement = target - nums[i];
            Integer idx = map.get(complement);
            if (idx != null) {
                return new int[] {idx, i};
            }
            // Store the current index for the number if not already present.
            // If the same number appears again, we keep the first index
            // as the problem guarantees a unique solution.
            map.putIfAbsent(nums[i], i);
        }
        // According to problem statement this should never happen
        throw new java.util.NoSuchElementException("No two sum solution found");
    } catch (RuntimeException e) {
        // Preserve original exception details
        throw e;
    }
}

