public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        return false;
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false; // cannot pair an odd number of elements
    }

    // Count occurrences of each remainder
    java.util.Map<Integer, Integer> remainderCount = new java.util.HashMap<>();
    for (int num : arr) {
        int rem = num % k;
        if (rem < 0) {
            rem += k;
        }
        remainderCount.merge(rem, 1, Integer::sum);
    }

    for (java.util.Map.Entry<Integer, Integer> entry : remainderCount.entrySet()) {
        int r = entry.getKey();
        int count = entry.getValue();

        if (r == 0) {
            if (count % 2 != 0) {
                return false;
