public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0) return 0;
    // Build adjacency list
    java.util.List<Integer>[] adj = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new java.util.ArrayList<>();
    }
    for (int[] e : edges) {
        int u = e[0];
        int v = e[1];
        adj[u].add(v);
        adj[v].add(u);
    }

    // Stack for iterative DFS: each element is int[]{node, parent, visitedFlag}
    java.util.Stack<int[]> stack = new java.util.Stack<>();
    stack.push(new int[]{0, -1, 0});

    boolean[] subtreeHasApple = new boolean[n];
    int[] time = new int[1]; // use array to allow modification inside loop

    while (!stack.isEmpty()) {
        int[] current = stack.pop();
        int node = current[0];
        int parent = current[1];
        int visited = current[2];

        if (visited == 0) {
            // First time we see this node: push again as visited, then push children
            stack.push(new int[]{node, parent, 1});
            for (int neighbor : adj[node]) {
                if (neighbor == parent) continue;
                stack.push(new int[]{neighbor, node, 0});
            }
        } else {
            // All children processed; compute if this subtree has apple
            boolean has = hasApple[node];
            for (int neighbor : adj[node]) {
                if (neighbor == parent) continue;
                if (subtreeHasApple[neighbor]) {
                    has = true;
                    time[0] += 2;
                }
            }
            subtreeHasApple[node] = has;
        }
    }

    return time[0];
}

