public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    // Count occurrences of each char (Unicode range 0-65535)
    int[] cnt = new int[65536];
    for (int i = 0; i < s.length(); i++) {
        cnt[s.charAt(i)]++;
    }
    int total = s.length();
    StringBuilder result = new StringBuilder(total);

    while (total > 0) {
        // Ascending pass: smallest to largest
        int asc = -1;
        for (int i = 0; i < 65536; i++) {
            if (cnt[i] > 0) {
                asc = i;
                break;
            }
        }
        if (asc == -1) {
            break; // no characters left
        }
        result.append((char) asc);
        cnt[asc]--;
        total--;
        int cur = asc;
        while (true) {
            int next = -1;
            for (int i = cur + 1; i < 65536; i++) {
                if (cnt[i] > 0) {
                    next = i;
                    break;
                }
            }
            if (next == -1) {
                break;
            }
            result.append((char) next);
            cnt[next]--;
            total--;
            cur = next;
        }
        if (total == 0) {
            break;
        }

        // Descending pass: largest to smallest
        int desc = -1;
        for (int i = 65535; i >= 0; i--) {
            if (cnt[i] > 0) {
                desc = i;
                break;
            }
        }
        if (desc == -1) {
            break;
        }
        result.append((char) desc);
        cnt[desc]--;
        total--;
        cur = desc;
        while (true) {
            int next = -1;
            for (int i = cur - 1; i >= 0; i--) {
                if (cnt[i] > 0) {
                    next = i;
                    break;
                }
            }
            if (next == -1) {
                break;
            }
            result.append((char) next);
            cnt[next]--;
            total--;
            cur = next;
        }
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    // sumsByCount[k] will contain all possible sums using exactly k numbers
    @SuppressWarnings("unchecked")
    HashSet<Integer>[] sumsByCount = new HashSet[n + 1];
    for (int i = 0; i <= n; i++) {
        sumsByCount[i] = new HashSet<>();
    }
    sumsByCount[0].add(0);

    for (int num : nums) {
        // Update from higher k to lower to avoid using a number multiple times
        for (int k = n - 1; k >= 0; k--) {
            if (!sumsByCount[k].isEmpty()) {
                for (int existingSum : sumsByCount[k]) {
                    sumsByCount[k + 1].add(existingSum + num);
                }
            }
        }
    }

    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) {
            continue; // target sum must be integer
        }
        int targetSum = (totalSum * k) / n;
        if (sumsByCount[k].contains(targetSum)) {
            return true;
        }
    }
    return false;
}

