    }
    int n = cost.length;
    // dp[i] = min cost to reach step i (top is step n)
    // Start at step 0 or 1 with zero cost
    int prev2 = 0; // dp[i-2]
    int prev1 = 0; // dp[i-1]
    for (int i = 2; i <= n; i++) {
        // cost of stepping onto step i-1 (since steps are 0-indexed)
        int stepCost = cost[i - 1];
        int curr = Math.min(prev1 + stepCost, prev2 + stepCost);
        prev2 = prev1;
        prev1 = curr;
    }
    return n == 1 ? 0 : prev1;
}

