    if (n == 0) {
        return 0;
    }
    // dp[i] represents the minimum cost to reach step i (or the top at i = n).
    int[] dp = new int[n + 1];
    // Starting points: you can start at step 0 or step 1 without paying.
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        int fromPrev = dp[i - 1] + cost[i - 1];
        int fromPrevPrev = dp[i - 2] + cost[i - 2];
        dp[i] = Math.min(fromPrev, fromPrevPrev);
    }
    return dp[n];
}

