public boolean hasAllCodes(String s, int k) {
    if (k <= 0) {
        return true; // empty string always present
    }
    int n = s.length();
    if (n < k) {
        return false; // cannot contain all codes if shorter than k
    }
    // Number of possible binary codes of length k
    int totalCodes;
    try {
        totalCodes = 1 << k; // works safely for k < 31
    } catch (Exception e) {
        // In case of overflow (k too large), use a different approach
        // but problem constraints likely keep k small
        totalCodes = Integer.MAX_VALUE;
    }
    Set<Integer> seen = new HashSet<>(Math.min(totalCodes, n - k + 1));
    int mask = totalCodes - 1; // Keeps only the last k bits
    int value = 0;
    // Initialize the first window
    for (int i = 0; i < k; i++) {
        value = (value << 1) | (s.charAt(i) - '0');
    }
    seen.add(value);
    // Slide the window across the string
    for (int i = k; i < n; i++) {
        value = ((value << 1) & mask) | (s.charAt(i) - '0');
        seen.add(value);
    }
    return seen.size() == totalCodes;
}

public boolean hasAllCodes(String s, int k) {
    // Validate inputs
    if (s == null || k < 0) {
        return false;
    }
    int n = s.length();
    if (k == 0) {
        // Only one binary string of length 0: the empty string
        return true;
    }
    if (k > n) {
        return false;
    }

    int total = 1 << k; // number of distinct binary strings of length k
    boolean[] seen = new boolean[total];
    int mask = total - 1;
    int code = 0;

    // Build the initial code from the first k characters
    for (int i = 0; i < k; i++) {
        code = (code << 1) + (s.charAt(i) - '0');
    }
    seen[code] = true;
    int count = 1;

    // Slide the window through the string
    for (int i = k; i < n; i++) {
        code = ((code << 1) & mask) + (s.charAt(i) - '0');
        if (!seen[code]) {
            seen[code] = true;
            count++;
            if (count == total) {
                return true; // All codes have been seen
            }
        }
    }

    return count == total;
}

public boolean hasAllCodes(String s, int k) {
    // Handle null or empty inputs
    if (s == null || k < 0) {
        return false;
    }
    if (k == 0) {
        // Only one binary string of length 0: the empty string, which is always a substring
        return true;
    }
    int n = s.length();
    long totalCodes = 1L << k;
    if (totalCodes > Integer.MAX_VALUE) {
        // For very large k, array cannot be allocated; if s is long enough, use set
        // but to keep implementation simple, return false for such test cases
        return false;
    }
    int codes = (int) totalCodes;
    boolean[] seen = new boolean[codes];
    int seenCount = 0;
    int mask = 0;
    int maskLimit = (1 << k) - 1;
    for (int i = 0; i < n; i++) {
        int bit = s.charAt(i) - '0';
        if (bit < 0 || bit > 1) {
            // Invalid character in binary string
            return false;
        }
        mask = ((mask << 1) & maskLimit) | bit;
        if (i >= k - 1) {
            if (!seen[mask]) {
                seen[mask] = true;
                seenCount++;
                if (seenCount == codes) {
                    return true; // All codes found early
                }
            }
        }
    }
    return seenCount == codes;
}

public boolean hasAllCodes(String s, int k) {
    // Handle null or empty string input
    if (s == null || s.isEmpty() || k < 0) {
        return false;
    }

    int n = s.length();

    // Edge case: k == 0 => only the empty string, which is always a substring
    if (k == 0) {
        return true;
    }

    // If the string is shorter than k, it can't contain all k-length codes
    if (n < k) {
        return false;
    }

    // Use a HashSet to record the distinct k-length codes seen
    java.util.HashSet<Integer> seen = new java.util.HashSet<>();

    // Compute the bit mask for the first k characters
    int mask = 0;
    for (int i = 0; i < k; i++) {
        mask = (mask << 1) | (s.charAt(i) - '0');
    }
    seen.add(mask);

    // Mask to keep only the last k bits
    int limit = (1 << k) - 1;

    // Slide the window along the string
    for (int i = k; i < n; i++) {
        // Shift left, add new bit, and mask to k bits
        mask = ((mask << 1) & limit) | (s.charAt(i) - '0');
        seen.add(mask);
    }

    // Number of possible binary strings of length k
    long totalCodes = 1L << k;
    return seen.size() == totalCodes;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null) {
        return false;
    }
    if (k <= 0) {
        return true; // All empty codes are trivially present
    }
    int n = s.length();
    if (n < k) {
        return false;
    }

    // Compute number of distinct binary strings of length k (2^k)
    // Guard against overflow for large k
    if (k >= 31) {
        // Too many distinct codes to be feasibly present in most strings
        return false;
    }
    long requiredCodes = 1L << k; // 2^k
    // The maximum number of substrings of length k in s is n - k + 1
    if (requiredCodes > n - k + 1) {
        return false;
    }

    // Use a HashSet to track seen codes
    java.util.HashSet<Integer> seen = new java.util.HashSet<>((int) requiredCodes);
    int mask = (int) ((1L << k) - 1); // bitmask to keep only k bits
    int current = 0;

    for (int i = 0; i < n; i++) {
        char c = s.charAt(i);
        if (c != '0' && c != '1') {
            // Non-binary character encountered; cannot be a valid binary string
            return false;
        }
        current = ((current << 1) & mask) | (c - '0');
        if (i >= k - 1) {
            seen.add(current);
            if (seen.size() == requiredCodes) {
                return true; // All codes found early
            }
        }
    }
    return seen.size() == requiredCodes;
}

public int isPrefixOfWord(String sentence, String searchWord) {
    // Handle null or empty inputs gracefully
    if (sentence == null || searchWord == null || searchWord.isEmpty()) {
        return -1;
    }
    try {
        // Split the sentence into words using one or more whitespace characters
        String[] words = sentence.trim().split("\\s+");
        for (int i = 0; i < words.length; i++) {
            String word = words[i];
            if (word != null && word.startsWith(searchWord)) {
                // Return 1-based index of the first matching word
                return i + 1;
            }
        }
        // No matching prefix found
        return -1;
    } catch (Exception e) {
        // Return -1 in case of unexpected runtime issues
        return -1;
    }
}

