public int minInsertions(String s) {
    // Handle null or empty input
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int insertions = 0;
    int balance = 0; // current number of unmatched '('

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            balance--;
            if (balance < 0) {
                // We have an unmatched ')' -> need to insert a '(' before it
                insertions++;
                balance = 0; // after inserting, balance becomes 0
            }
        } else {
            // Invalid character encountered
            throw new IllegalArgumentException("Input string contains invalid characters. Only '(' and ')' are allowed.");
        }
    }

    // Any remaining unmatched '(' requires a ')' to balance
    insertions += balance;

    return insertions;
}

