    }
    int leftNeeded = 0;   // number of '(' needed to match closing brackets
    int rightNeeded = 0;  // number of ')' needed to close unmatched opening brackets
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            leftNeeded++;
        } else if (c == ')') {
            if (leftNeeded == 0) {
                // no unmatched '(' available, need to insert one before this ')'
                rightNeeded++;
            } else {
                // match this ')' with a previous '('
                leftNeeded--;
            }
        } else {
            throw new IllegalArgumentException("Invalid character '" + c + "'. Only '(' and ')' are allowed.");
        }
    }
    return leftNeeded + rightNeeded;
}

