public int minOperations(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }
    if (n == 0) {
        return 0;
    }
    long target = n;
    long sumSurplus = 0;
    for (int i = 0; i < n; i++) {
        long diff = 2L * i + 1 - target;
        if (diff > 0) {
            sumSurplus += diff;
        }
    }
    if (sumSurplus > Integer.MAX_VALUE) {
        throw new ArithmeticException("Result exceeds int range");
    }
    return (int) sumSurplus;
}

public int minOperations(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    int s = (n + 1) / 2; // ceil(n/2)
    long ops = (long) s * (n - s);
    if (ops > Integer.MAX_VALUE) {
        throw new ArithmeticException("Result exceeds integer range");
    }
    return (int) ops;
}

