    fibs[size++] = 1;
    while (true) {
        long next = (long) fibs[size - 1] + fibs[size - 2];
        if (next > k) {
            break;
        }
        fibs[size++] = (int) next;
    }

    // Greedy subtraction
    int count = 0;
    for (int i = size - 1; i >= 0; i--) {
        if (k == 0) {
            break;
        }
        if (k >= fibs[i]) {
            k -= fibs[i];
            count++;
        }
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("k must be a positive integer");
    }

    // Generate Fibonacci numbers up to k
    int[] fib = new int[50]; // 50 is enough for k up to 10^9
    int size = 0;

    // First Fibonacci numbers
    fib[size++] = 1;
    int a = 1; // Fn-2
    int b = 1; // Fn-1

    while (b <= k) {
        // Ensure capacity
        if (size == fib.length) {
            int[] newFib = new int[fib.length * 2];
            System.arraycopy(fib, 0, newFib, 0, fib.length);
            fib = newFib;
        }
        fib[size++] = b;
        int next = a + b;
        a = b;
        b = next;
    }

    // Greedy subtraction
    int count = 0;
    int remaining = k;
    for (int i = size - 1; i >= 0 && remaining > 0; i--) {
        if (fib[i] <= remaining) {
            remaining -= fib[i];
            count++;
        }
    }

    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.ArrayList<Integer> factors = new java.util.ArrayList<>();
    for (int i = 1; i <= n / i; i++) {
        if (n % i == 0) {
            factors.add(i);
            int paired = n / i;
            if (paired != i) {
                factors.add(paired);
            }
        }
    }
    java.util Collections.sort(factors);
    if (k <= factors.size()) {
        return factors.get(k - 1);
    } else {
        return -1;
    }
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) return -1;
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> large = new java.util.ArrayList<>();
    for (int i = 1; (long)i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            int complement = n / i;
            if (complement != i) {
                large.add(complement);
            }
        }
    }
    int count = 0;
    for (int val : small) {
        count++;
        if (count == k) return val;
    }
    for (int i = large.size() - 1; i >= 0; i--) {
        count++;
        if (count == k) return large.get(i);
    }
    return -1;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> largeRev = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            int other = n / i;
            if (i != other) {
                largeRev.add(other);
            }
        }
    }
    int smallCount = small.size();
    if (k <= smallCount) {
        return small.get(k - 1);
    }
    int idx = k - smallCount; // 1-based index into ascending order of large factors
    if (idx <= largeRev.size()) {
        return largeRev.get(largeRev.size() - idx);
    } else {
        return -1;
    }
}

public String makeGood(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    char[] stack = new char[s.length()];
    int top = 0;
    for (char c : s.toCharArray()) {
        if (top > 0 && Math.abs(stack[top - 1] - c) == 32) {
            top--; // pop
        } else {
            stack[top++] = c; // push
        }
    }
    return new String(stack, 0, top);
}

public String makeGood(String s) {
    if (s == null || s.length() == 0) {
        return s == null ? "" : s;
    }
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char current = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char last = stack.charAt(len - 1);
            // Check if last and current are same letter in opposite cases
            if (Math.abs(last - current) == 32) {
                stack.deleteCharAt(len - 1);
                continue;
            }
        }
        stack.append(current);
    }
    return stack.toString();
}

