public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    return dfs(0, s, new java.util.HashSet<>());
}

private int dfs(int pos, String s, java.util.Set<String> used) {
    int n = s.length();
    if (pos == n) {
        return 0;
    }
    int maxCount = 0;
    for (int len = 1; len <= n - pos; len++) {
        String sub = s.substring(pos, pos + len);
        if (used.contains(sub)) {
            continue;
        }
        used.add(sub);
        int current = 1 + dfs(pos + len, s, used);
        if (current > maxCount) {
            maxCount = current;
        }
        used.remove(sub);
    }
    return maxCount;
}

public int maxUniqueSplit(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }
    java.util.Set<String> used = new java.util.HashSet<>();
    int[] max = new int[1];
    backtrack(s, 0, used, max);
    return max[0];
}

private void backtrack(String s, int index, java.util.Set<String> used, int[] max) {
    if (index == s.length()) {
        if (used.size() > max[0]) {
            max[0] = used.size();
        }
        return;
    }
    for (int end = index + 1; end <= s.length(); end++) {
        String sub = s.substring(index, end);
        if (!used.contains(sub)) {
            used.add(sub);
            backtrack(s, end, used, max);
            used.remove(sub);
        }
    }
}

