    return max[0];
}

private void dfs(String s, int index, java.util.Set<String> seen, int count, int[] max) {
    if (index == s.length()) {
        if (count > max[0]) {
            max[0] = count;
        }
        return;
    }
    for (int end = index + 1; end <= s.length(); end++) {
        String sub = s.substring(index, end);
        if (!seen.contains(sub)) {
            seen.add(sub);
            dfs(s, end, seen, count + 1, max);
            seen.remove(sub);
        }
    }
}

