}

private void backtrack(String s, int index, java.util.HashSet<String> used, int[] maxCount) {
    if (index == s.length()) {
        maxCount[0] = Math.max(maxCount[0], used.size());
        return;
    }
    for (int end = index + 1; end <= s.length(); end++) {
        String sub = s.substring(index, end);
        if (!used.contains(sub)) {
            used.add(sub);
            backtrack(s, end, used, maxCount);
            used.remove(sub);
        }
    }
}

