    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }

    int remaining = k - n; // additional value to distribute

    // Distribute the additional value starting from the end to keep lexicographic order minimal
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // each position can be increased by at most 25
        result[i] = (char) ('a' + add);
        remaining -= add;
    }

    return new String(result);
}

public String getSmallestString(int n, int k) {
    // Validate input: each character contributes at least 1 (a) and at most 26 (z)
    if (n <= 0 || k < n || k > 26 * n) {
        return "";
    }

    // Start with the smallest lexicographic string: all 'a'
    char[] result = new char[n];
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }

    // The extra value needed beyond the all-'a' baseline
    int extra = k - n;

    // Distribute the extra value from the end towards the start
    for (int i = n - 1; i >= 0 && extra > 0; i--) {
        int add = Math.min(25, extra); // each char can increase by at most 25 (a->z)
        result[i] = (char) (result[i] + add);
        extra -= add;
    }

    return new String(result);
}

public String getSmallestString(int n, int k) {
    if (n <= 0) {
        throw new IllegalArgumentException("Length must be positive");
    }
    if (k < n || k > 26L * n) {
        throw new IllegalArgumentException("k out of valid range for given n");
    }
    StringBuilder sb = new StringBuilder(n);
    int remaining = k - n; // how much extra value to distribute
    for (int i = 0; i < n; i++) {
        sb.append('a');
    }
    int idx = n - 1;
    while (remaining > 0 && idx >= 0) {
        int add = Math.min(remaining, 25);
        char c = (char) ('a' + add);
        sb.setCharAt(idx, c);
        remaining -= add;
        idx--;
    }
    return sb.toString();
}

