public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0; // If array is empty or null, no single element exists
    }
    int ones = 0; // Bits that have appeared 1 time mod 3
    int twos = 0; // Bits that have appeared 2 times mod 3
    for (int x : nums) {
        // Update bits that have appeared twice
        twos |= ones & x;
        // Update bits that have appeared once
        ones ^= x;
        // Remove bits that have appeared three times
        int mask = ~(ones & twos);
        ones &= mask;
        twos &= mask;
    }
    return ones;
}

public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int result = 0;
    for (int bit = 0; bit < 32; bit++) {
        int bitCount = 0;
        for (int num : nums) {
            bitCount += (num >> bit) & 1;
        }
        if ((bitCount % 3) != 0) {
            result |= (1 << bit);
        }
    }
    return result;
}

public static int singleNumber(int[] nums) {
    if (nums == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int ones = 0;   // bits which have appeared once
    int twos = 0;   // bits which have appeared twice
    for (int num : nums) {
        // Update twos with bits that have appeared twice
        twos |= (ones & num);
        // Update ones with bits that have appeared once
        ones ^= num;
        // Mask to remove bits that have appeared three times
        int mask = ~(ones & twos);
        ones &= mask;
        twos &= mask;
    }
    return ones; // the number that appears only once
}

public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array must not be null or empty");
    }
    int ones = 0;
    int twos = 0;
    for (int num : nums) {
        // Update bits that have appeared twice so far
        int newTwos = twos | (ones & num);
        // Update bits that have appeared once so far, removing bits that are now in twos
        int newOnes = (ones ^ num) & ~newTwos;
        twos = newTwos;
        ones = newOnes;
    }
    return ones;
}

public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array must not be null or empty");
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        long sum = 0;
        for (int num : nums) {
            sum += ((num >>> i) & 1L);
        }
        if ((sum % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }
    // Include 0 if it's within the range
    if (low <= 0 && high >= 0) {
        result.add(0);
    }
    Queue<Long> queue = new LinkedList<>();
    // Initialize queue with digits 1 to 9
    for (long i = 1; i <= 9; i++) {
        queue.offer(i);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add((int) num);
        }
        int lastDigit = (int) (num % 10);
        if (lastDigit > 0) {
            long next = num * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        if (lastDigit < 9) {
            long next = num * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }
    Collections.sort(result);
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> steppingNumbers = new ArrayList<>();
    if (low > high) {
        return steppingNumbers;
    }
    // Include 0 if it falls within the range
    if (low <= 0 && 0 <= high) {
        steppingNumbers.add(0);
    }
    // Use BFS to generate stepping numbers
    Queue<Long> queue = new LinkedList<>();
    // Initial single-digit numbers (1-9)
    for (int i = 1; i <= 9; i++) {
        queue.add((long) i);
    }
    long highLong = (long) high;
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > highLong) {
            continue;
        }
        if (num >= low) {
            steppingNumbers.add((int) num);
        }
        long lastDigit = num % 10;
        // Append next digit larger by 1
        if (lastDigit < 9) {
            long next = num * 10 + (lastDigit + 1);
            if (next <= highLong) {
                queue.add(next);
            }
        }
        // Append next digit smaller by 1
        if (lastDigit > 0) {
            long next = num * 10 + (lastDigit - 1);
            if (next <= highLong) {
                queue.add(next);
            }
        }
    }
    Collections.sort(steppingNumbers);
    return steppingNumbers;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }
    // Handle potential negative bounds by adjusting to zero
    int start = Math.max(low, 0);
    int end = high;
    Queue<Long> queue = new LinkedList<>();

    // Initialize queue with single digit numbers 0-9
    for (int i = 0; i <= 9; i++) {
        queue.offer((long) i);
    }

    while (!queue.isEmpty()) {
        long current = queue.poll();

        if (current > end) {
            continue;
        }

        if (current >= start) {
            // current fits within the given range
            result.add((int) current);
        }

        // Skip generating next numbers from 0 to avoid leading zeros
        if (current == 0) {
            if (1 <= end) {
                queue.offer(1);
            }
            continue;
        }

        int lastDigit = (int) (current % 10);
        // Next possible digits: lastDigit-1 and lastDigit+1
        if (lastDigit > 0) {
            long next = current * 10 + (lastDigit - 1);
            if (next <= end) {
                queue.offer(next);
            }
        }
        if (lastDigit < 9) {
            long next = current * 10 + (lastDigit + 1);
            if (next <= end) {
                queue.offer(next);
            }
        }
    }

    Collections.sort(result);
    return result;
}

public static java.util.List<Integer> findSteppingNumbers(int low, int high) {
    java.util.List<Integer> res = new java.util.ArrayList<>();
    if (high < 0) return res;
    if (low <= 0 && high >= 0) res.add(0);
    java.util.Deque<Long> queue = new java.util.ArrayDeque<>();
    for (int i = 1; i <= 9; i++) {
        queue.add((long) i);
    }
    while (!queue.isEmpty()) {
        long cur = queue.poll();
        if (cur > high) continue;
        if (cur >= low) {
            res.add((int) cur);
        }
        int last = (int) (cur % 10);
        if (last > 0) {
            long next = cur * 10 + (last - 1);
            if (next <= high) queue.add(next);
        }
        if (last < 9) {
            long next = cur * 10 + (last + 1);
            if (next <= high) queue.add(next);
        }
    }
    java.util.Collections.sort(res);
    return res;
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    while (factor <= n) {
        long lower = n - (n / factor) * factor; // n % factor
        long current = (n / factor) % 10;
        long higher = n / (factor * 10);
        if (current == 0) {
            count += higher * factor;
        } else if (current == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
        factor *= 10;
    }
    return (int) count;
}

