public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    boolean negative = n < 0;
    int abs = Math.abs(n);
    StringBuilder sb = new StringBuilder();
    while (abs > 0) {
        int segment = abs % 1000;
        abs /= 1000;
        if (abs > 0) {
            sb.insert(0, String.format("%03d", segment));
            sb.insert(0, '.');
        } else {
            sb.insert(0, String.valueOf(segment));
        }
    }
    if (negative) {
        sb.insert(0, '-');
    }
    return sb.toString();
}

