        int r = (int) Math.sqrt(sum);
        return r * r == sum;
    };

    java.util.function.Consumer<Integer> dfs = new java.util.function.Consumer<Integer>() {
        @Override
        public void accept(Integer depth) {
            if (depth == n) {
                result[0]++;
                return;
            }
            for (int i = 0; i < n; i++) {
                if (used[i]) continue;
                if (i > 0 && arr[i] == arr[i - 1] && !used[i - 1]) continue;
                if (depth == 0 || isSquare.apply(arr[depth - 1] + arr[i])) {
                    used[i] = true;
                    dfs.accept(depth + 1);
                    used[i] = false;
                }
            }
        }
    };

    dfs.accept(0);
    return result[0];
}

