        int startRow = Math.max(0, sum - n + 1);
        int count = Math.min(Math.min(sum, m - 1 - startRow), n - 1) + 1;
        if (sum % 2 == 0) { // even sum -> traverse bottom-up
            int r = startRow + count - 1;
            int c = sum - r;
            for (int k = 0; k < count; k++) {
                result[index++] = mat[r][c];
                r--;
                c++;
            }
        } else { // odd sum -> traverse top-down
            int r = startRow;
            int c = sum - r;
            for (int k = 0; k < count; k++) {
                result[index++] = mat[r][c];
                r++;
                c--;
            }
        }
    }
    return result;
}

