public static java.util.List<String> centerSymmetricNumbers(int n) {
    java.util.List<String> result = new java.util.ArrayList<>();
    if (n <= 0) {
        return result;
    }
    char[] arr = new char[n];
    generate(arr, 0, n - 1, result);
    return result;
}

private static void generate(char[] arr, int l, int r, java.util.List<String> res) {
    if (l > r) {
        res.add(new String(arr));
        return;
    }
    if (l == r) {
        char[] middle = {'0', '1', '8'};
        for (char c : middle) {
            arr[l] = c;
            res.add(new String(arr));
        }
        return;
    }
    char[][] pairs = {{'0', '0'}, {'1', '1'}, {'6', '9'}, {'8', '8'}, {'9', '6'}};
    for (char[] p : pairs) {
        if (l == 0 && p[0] == '0') { // avoid leading zero for numbers longer than 1 digit
            continue;
        }
        arr[l] = p[0];
        arr[r] = p[1];
        generate(arr, l + 1, r - 1, res);
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    char[][] pairs = {{'0', '0'}, {'1', '1'}, {'6', '9'}, {'8', '8'}, {'9', '6'}};
    char[] current = new char[n];
    build(0, n - 1, current, pairs, result, n);
    return result;
}

private static void build(int left, int right, char[] arr, char[][] pairs, List<String> res, int totalLen) {
    if (left > right) {
        res.add(new String(arr));
        return;
    }
    for (char[] p : pairs) {
        if (left == 0 && totalLen > 1 && p[0] == '0') {
            continue; // avoid leading zero for multi-digit numbers
        }
        if (left == right && p[0] != p[1]) {
            continue; // middle digit must be symmetric
        }
        arr[left] = p[0];
        arr[right] = p[1];
        build(left + 1, right - 1, arr, pairs, res, totalLen);
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    result.addAll(helper(n, n));
    return result;
}

private static List<String> helper(int current, int total) {
    List<String> res = new ArrayList<>();
    if (current == 0) {
        res.add("");
        return res;
    }
    if (current == 1) {
        res.add("0");
        res.add("1");
        res.add("8");
        return res;
    }
    List<String> sub = helper(current - 2, total);
    for (String s : sub) {
        if (current != total) {
            res.add("0" + s + "0");
        }
        res.add("1" + s + "1");
        res.add("6" + s + "9");
        res.add("8" + s + "8");
        res.add("9" + s + "6");
    }
    return res;
}

public static boolean isBoomerang(int[][] points) {
