        int x2 = points[1][0], y2 = points[1][1];
        int x3 = points[2][0], y3 = points[2][1];

        // Calculate twice the signed area of the triangle
        long area = (long)(x2 - x1) * (y3 - y1) - (long)(x3 - x1) * (y2 - y1);
        return area != 0;
    } catch (Exception e) {
        // In case of any runtime issues, treat as not a boomerang
        return false;
    }
}

