public static List<Integer> lexicalOrder(int n) {
    // Handle non-positive n
    if (n <= 0) {
        return new ArrayList<>();
    }
    List<Integer> result = new ArrayList<>(n);
    long current = 1;
    while (result.size() < n) {
        result.add((int) current);
        if (current <= n / 10) {
            // Go deeper: append a 0 to current number
            current *= 10;
        } else {
            // If we can't go deeper, move to the next sibling
            if (current % 10 != 9 && current + 1 <= n) {
                current++;
            } else {
                // Backtrack: remove trailing 9s or overflow
                while ((current / 10) > 0 && (current % 10 == 9 || current + 1 > n)) {
                    current /= 10;
                }
                current++;
            }
        }
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    for (int i = 1; i < 10; i++) {
        if (i > n) break;
        dfs(i, result, n);
    }
    return result;
}

private static void dfs(long current, List<Integer> result, int n) {
    if (current > n) {
        return;
    }
    result.add((int) current);
    long next = current * 10;
    for (long j = next; j <= n && j <= next + 9; j++) {
        dfs(j, result, n);
    }
}

public static java.util.List<Integer> lexicalOrder(int n) {
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (n < 1) {
        return result;
    }
    long cur = 1;
    for (int i = 0; i < n; i++) {
        result.add((int) cur);
        if (cur * 10 <= n) {
            cur *= 10;
        } else {
            if (cur % 10 != 9 && cur + 1 <= n) {
                cur++;
            } else {
                while (cur % 10 == 9) {
                    cur /= 10;
                }
                cur++;
            }
        }
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : nums) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

