public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    final int INF = Integer.MAX_VALUE / 2;
    for (int i = 0; i <= n; i++) {
        dp[i] = INF;
    }
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            int candidate = dp[i - square] + 1;
            if (candidate < dp[i]) {
                dp[i] = candidate;
            }
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    // dp[i] will hold the minimum number of perfect squares that sum to i
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int sq = j * j;
            int candidate = dp[i - sq] + 1;
            if (candidate < min) {
                min = candidate;
            }
        }
        dp[i] = min;
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n < 1) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }
    // dp[i] will hold the minimum number of perfect squares that sum to i
    int[] dp = new int[n + 1];
    // Initialize with a value greater than any possible answer (at most n)
    int INF = n + 1;
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = INF;
        // Try all perfect squares <= i
        for (int j = 1; j * j <= i; j++) {
            int candidate = dp[i - j * j] + 1;
            if (candidate < min) {
                min = candidate;
            }
        }
        dp[i] = min;
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    // Handle non-positive input: no perfect squares sum to a non-positive number
    if (n <= 0) {
        return 0;
    }

    int[] dp = new int[n + 1];
    // dp[0] is already 0, representing 0 perfect squares needed for sum 0
    for (int i = 1; i <= n; i++) {
        int minCount = Integer.MAX_VALUE;
        // Try all perfect squares less than or equal to i
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            int candidate = dp[i - square] + 1;
            if (candidate < minCount) {
                minCount = candidate;
            }
        }
        dp[i] = minCount;
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    int n = s.length();
    for (int i = 0; i < n; i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            result.append(word.reverse());
            word.setLength(0);
            result.append(' ');
        } else {
            word.append(c);
        }
    }
    // Append the last word (if any)
    result.append(word.reverse());
    return result.toString();
}

